{
  "title": "断剑崖",
  "scene": "你站在一片荒凉的山崖之上，崖下是万丈深渊，崖边长满了荆棘。面前有一座古老的石碑，上面刻着一行字：‘断剑何处寻，缘起缘灭无常。’周围雾气缭绕，隐约能听到远处传来阵阵剑鸣声。",
  "goal": "找到断剑，并解开石碑上的谜题，才能继续前行。",
  "choices": [
    {
      "id": "A",
      "text": "沿着雾气的方向探索，寻找剑鸣的来源。",
      "outcome": "你朝着声音来源走去，穿过一片密林，发现一名衣衫褴褛的剑客正与一只怪兽搏斗，剑光闪烁，场面颇为壮观。",
      "result": "partial",
      "next": "B"
    },
    {
      "id": "B",
      "text": "仔细观察石碑上的每一个字，试图从中找出线索。",
      "outcome": "你蹲下仔细观看，发现石碑的底座有一处凹陷，按压凹陷处，石碑缓缓转动，露出一个隐藏的机关。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "直接向石碑发射飞镖，试图破坏石碑上的机关。",
      "outcome": "你的飞镖击中了石碑，石碑上裂开了一条裂缝，但裂缝并未打开机关，反而引来了一群守卫。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
